from pathlib import Path
import re,json,subprocess,os
root=Path.cwd()
def edit(path,fn):
 p=root/path;p.write_text(fn(p.read_text()))
def section(path,heading,body):
 p=root/path;s=p.read_text();pattern=re.compile(r'^'+re.escape(heading)+r'\n.*?(?=^## |\Z)',re.M|re.S)
 replacement=heading+'\n\n'+body.strip()+'\n\n'
 if pattern.search(s):s=pattern.sub(lambda _:replacement,s,count=1)
 else:s=s.rstrip()+'\n\n'+replacement
 p.write_text(s)

# Keep the native executor generic while locating the bundled-world balance in its owner.
p=root/'packages/domain/src/follow.ts';s=p.read_text();m=re.search(r'export const FOLLOW_RULES = \{.*?\n\} as const;\n',s,re.S)
if not m:raise RuntimeError('Follow-rule ownership changed')
(root/'packages/domain/src/worlds/base/navigation.ts').write_text('/** Bundled-world follow tuning; the generic executor remains in domain/follow.ts.\n * docs/worlds/base/navigation.md#native-follow\n */\n'+m.group())
p.write_text(s[:m.start()]+"import { FOLLOW_RULES } from './worlds/base/navigation.js';\nexport { FOLLOW_RULES } from './worlds/base/navigation.js';\n"+s[m.end():])
# Missing fields in an old unresolved intention imply no target and no replace authority.
p=root/'apps/server/src/upgrade-world.ts';s=p.read_text();anchor='export function upgradeWorldState(world: WorldState): void {'
s=s.replace(anchor,anchor+'''
  // Earlier pending requests had no explicit target/mode scope. Preserve the request;
  // a stored alternative retains its mode, otherwise queueing grants no replace authority.
  for (const entity of Object.values(world.entities ?? {})) {
    const attempts = entity.actor?.agency?.attempts;
    if (!Array.isArray(attempts)) continue;
    for (const attempt of attempts) {
      if (!attempt || typeof attempt !== 'object') continue;
      if (!Object.hasOwn(attempt, 'targetEntityId')) attempt.targetEntityId = null;
      if (!Object.hasOwn(attempt, 'mode')) attempt.mode = attempt.alternative?.mode ?? 'enqueue';
    }
  }
''',1);p.write_text(s)

(root/'docs/worlds/base/navigation.md').write_text('''# Base-world navigation behavior

## Native follow

The bundled world supplies the follow tuning in `packages/domain/src/worlds/base/navigation.ts`: default separation 3 world units, accepted separation 1.5–12 units, a 0.75-unit hold/resume margin, and replanning after at least 1 unit of observed target displacement with a 4-game-second cadence. An empty route can require immediate route work. These are supplied-world choices, not universal rules for every authored reality.

The trusted executor owns movement, collision, current-perception checks and cancellation through the ordinary actor action lane. Follow currently means proximity to a visible living actor on supported ground. It ends honestly when perception, locomotion/actions capability, target viability or route support is lost. It does not implement stealth, scent, behind/beside formation, or sunset termination. Holding position remains ongoing work.

The root `follow.ts` re-export preserves current consumers of the single rule source; it is not another writable registry. A configurable installed navigation family is the extension trigger, not an unused loader now. See [capability contracts](../../action-capabilities.md), [spatial ownership](../../spatial-world.md), and [current implementation](../../architecture.md#native-follow-activity).
''')
p=root/'docs/worlds/base/README.md';p.write_text(p.read_text().rstrip()+'\n\n- [Navigation behavior](navigation.md) — bundled follow tuning and its current boundaries.\n')

